-- BACKUP: bak_20261026_rc_contract_workflow
-- Rollback: UPDATE fleet_tasks SET definition = json_remove(definition, '$.steps[' || (SELECT j.key FROM json_each(fleet_tasks.definition, '$.steps') j WHERE json_extract(j.value, '$.name') = 'rc-contract') || ']'), version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 'management-personas' AND EXISTS (SELECT 1 FROM json_each(fleet_tasks.definition, '$.steps') j WHERE json_extract(j.value, '$.name') = 'rc-contract'); UPDATE remediation_contracts SET status = 'superseded', verify_transport = 'd1-query', module = 'probe-template-v3-generic', attempts = 0, deferred_since = NULL, next_due_at = NULL, last_verdict = 'superseded:closure-observing-probe-at-birth (CLOSE-PROBE-CIRCULAR-1: this template observes the guarded issue status, which issue_close_evidence_required only lets change after a close that the same probe blocks; a doer that knows the defect replaces it with a probe that measures it)', precondition = 'no earlier birth template matched this issue (ORPHAN-GUARD-BIRTH-1)', action = 'VACUOUS-PROBE-V3-1: this contract measures nothing while the issue is open, so it is born superseded and never blocks the close. A doer that knows the defect replaces this probe with one that measures it.', verify_probe = 'SELECT ''closed'' AS expected, (SELECT CASE WHEN status IN (''closed'', ''resolved'') THEN ''closed'' ELSE NULL END FROM agent_issues WHERE id = ' || substr(class, 7) || ') AS observed' WHERE module = 'probe-template-v4-root-cause'; UPDATE remediation_contracts SET issue_id = (SELECT b.issue_id FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), status = (SELECT b.status FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), verify_probe = (SELECT b.verify_probe FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), verify_transport = (SELECT b.verify_transport FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), last_verdict = (SELECT b.last_verdict FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), module = (SELECT b.module FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), action = (SELECT b.action FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), precondition = (SELECT b.precondition FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), attempts = (SELECT b.attempts FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), next_due_at = (SELECT b.next_due_at FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), deferred_since = (SELECT b.deferred_since FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class), expected_cadence_h = (SELECT b.expected_cadence_h FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class) WHERE module = 'probe-template-v3-generic' AND class IN (SELECT class FROM bak_20261026_rc_contract_contracts); UPDATE remediation_contracts SET next_due_at = (SELECT b.next_due_at FROM bak_20261026_rc_contract_contracts b WHERE b.class = remediation_contracts.class) WHERE module = 'probe-template-v3-generic' AND class IN (SELECT class FROM bak_20261026_rc_contract_contracts)
-- ROOT-CAUSE-CONTRACT-1 (2026-10-26, charter pillar autonomy; agent_issues 1000419). Follows ROOT-CAUSE-PROBE-AT-BIRTH-1.
-- WHAT WAS FOUND (read 2026-10-26, SELECT only): each ROOT-CAUSE-1 ticket filed by the management-personas workflow (step rc-file) is born with the generic contract
--   (status superseded, module probe-template-v3-generic, action VACUOUS-PROBE-V3-1), which the PROBE-NEEDED-1 filer does not count as live, so every ticket bred a twin (16 open for 10 tickets).
-- WHAT THIS DOES: gives each such ticket a contract that measures its own closing condition, and keeps doing so for the tickets filed later.
--   Probe (d1-query, status active, last_verdict NULL): expected 0, observed = the family reopens_24h + opens_24h in issue_recurrence_now, +1 while the ticket is under 24 hours old,
--   +1 while issue_recurrence_now is empty (recur-clear and recur-snapshot are two requests; an empty table would read as quiet). It reads the snapshot, never v_root_cause_quiet:
--   that view hides a ticket whose own active contract reads fail, so a probe that waited for the view could never turn true. The probe's condition is the view's own condition
--   minus its contract clause, so the first quiet read passes, the contract stops failing, the view lists the ticket and rc-close closes it with evidence.
--   Step rc-contract is appended to the workflow (json_insert cannot place a step mid-array) and is a no-op unless a superseded VACUOUS-PROBE-V3-1 contract of an open ROOT-CAUSE-1 ticket exists.
-- spof-review: no new loop, cap, hold or gate. One workflow step, ten contracts re-pointed, two backup tables (bak_20261026_rc_contract_workflow, bak_20261026_rc_contract_contracts); the Rollback line removes the step and restores both.

CREATE TABLE IF NOT EXISTS bak_20261026_rc_contract_workflow AS SELECT id, definition, version, updated_at FROM fleet_tasks WHERE id = 'management-personas';

CREATE TABLE IF NOT EXISTS bak_20261026_rc_contract_contracts AS SELECT class, issue_id, ts, status, verify_probe, verify_transport, last_verdict, module, action, precondition, attempts, max_attempts, next_due_at, deferred_since, last_attempt_at, expected_cadence_h FROM remediation_contracts WHERE status = 'superseded' AND substr(action, 1, 18) = 'VACUOUS-PROBE-V3-1' AND class IN (SELECT 'issue-' || id FROM agent_issues WHERE status = 'open' AND title LIKE 'ROOT-CAUSE-1: % keeps recurring' AND instr(title, ';') = 0);

UPDATE fleet_tasks SET definition = json_insert(definition, '$.steps[#]', json_object('type', 'sql', 'name', 'rc-contract', 'db', 'AUDIT', 'sql', 'UPDATE remediation_contracts SET verify_probe = (SELECT ''SELECT ''''0'''' AS expected, CAST((SELECT COALESCE(SUM(r.reopens_24h + r.opens_24h), 0) FROM issue_recurrence_now r WHERE r.family = '''''' || replace(substr(a.title, 15, instr(a.title, '' keeps recurring'') - 15), '''''''', '''''''''''') || '''''') + (SELECT CASE WHEN COUNT(*) = 0 THEN 1 ELSE 0 END FROM issue_recurrence_now) + COALESCE((SELECT CASE WHEN x.created_at < (CAST(strftime(''''%s'''', ''''now'''') AS INTEGER) - 86400) * 1000 THEN 0 ELSE 1 END FROM agent_issues x WHERE x.id = '' || a.id || ''), 0) AS TEXT) AS observed'' FROM agent_issues a WHERE a.id = CAST(substr(remediation_contracts.class, 7) AS INTEGER)), verify_transport = ''d1-query'', issue_id = CAST(substr(remediation_contracts.class, 7) AS INTEGER), status = ''active'', last_verdict = NULL, attempts = 0, deferred_since = NULL, next_due_at = datetime(''now''), expected_cadence_h = 1, module = ''probe-template-v4-root-cause'', precondition = ''ROOT-CAUSE-CONTRACT-1 (agent_issues 1000419): the ticket closes when its family has no reopen and no new issue for 24 hours'', action = ''MEASURES the closing condition: expected 0, observed the family reopens_24h plus opens_24h in issue_recurrence_now, plus 1 while the ticket is under 24 hours old, plus 1 while the snapshot is empty. It reads the snapshot and not v_root_cause_quiet, so a failing read never hides the ticket from the view that closes it. ROOT-CAUSE-CONTRACT-1.'' WHERE status = ''superseded'' AND substr(action, 1, 18) = ''VACUOUS-PROBE-V3-1'' AND EXISTS (SELECT 1 FROM agent_issues t WHERE t.id = CAST(substr(remediation_contracts.class, 7) AS INTEGER) AND ''issue-'' || t.id = remediation_contracts.class AND t.status = ''open'' AND t.title LIKE ''ROOT-CAUSE-1: % keeps recurring'' AND instr(t.title, '';'') = 0)')), version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 'management-personas' AND json_valid(definition) AND NOT EXISTS (SELECT 1 FROM json_each(fleet_tasks.definition, '$.steps') j WHERE json_extract(j.value, '$.name') = 'rc-contract');

UPDATE remediation_contracts SET verify_probe = (SELECT 'SELECT ''0'' AS expected, CAST((SELECT COALESCE(SUM(r.reopens_24h + r.opens_24h), 0) FROM issue_recurrence_now r WHERE r.family = ''' || replace(substr(a.title, 15, instr(a.title, ' keeps recurring') - 15), '''', '''''') || ''') + (SELECT CASE WHEN COUNT(*) = 0 THEN 1 ELSE 0 END FROM issue_recurrence_now) + COALESCE((SELECT CASE WHEN x.created_at < (CAST(strftime(''%s'', ''now'') AS INTEGER) - 86400) * 1000 THEN 0 ELSE 1 END FROM agent_issues x WHERE x.id = ' || a.id || '), 0) AS TEXT) AS observed' FROM agent_issues a WHERE a.id = CAST(substr(remediation_contracts.class, 7) AS INTEGER)), verify_transport = 'd1-query', issue_id = CAST(substr(remediation_contracts.class, 7) AS INTEGER), status = 'active', last_verdict = NULL, attempts = 0, deferred_since = NULL, next_due_at = datetime('now'), expected_cadence_h = 1, module = 'probe-template-v4-root-cause', precondition = 'ROOT-CAUSE-CONTRACT-1 (agent_issues 1000419): the ticket closes when its family has no reopen and no new issue for 24 hours', action = 'MEASURES the closing condition: expected 0, observed the family reopens_24h plus opens_24h in issue_recurrence_now, plus 1 while the ticket is under 24 hours old, plus 1 while the snapshot is empty. It reads the snapshot and not v_root_cause_quiet, so a failing read never hides the ticket from the view that closes it. ROOT-CAUSE-CONTRACT-1.' WHERE status = 'superseded' AND substr(action, 1, 18) = 'VACUOUS-PROBE-V3-1' AND EXISTS (SELECT 1 FROM agent_issues t WHERE t.id = CAST(substr(remediation_contracts.class, 7) AS INTEGER) AND 'issue-' || t.id = remediation_contracts.class AND t.status = 'open' AND t.title LIKE 'ROOT-CAUSE-1: % keeps recurring' AND instr(t.title, ';') = 0);
